CREATE TABLE IF NOT EXISTS "upstream_provider_observations" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "proxy_log_id" INTEGER, "site_id" INTEGER, "account_id" INTEGER, "route_id" INTEGER, "channel_id" INTEGER, "downstream_api_key_id" INTEGER, "requested_model" TEXT, "actual_model" TEXT, "upstream_path" TEXT, "is_stream" BOOLEAN, "parser_id" TEXT NOT NULL DEFAULT 'cline-gateway', "parser_version" INTEGER NOT NULL DEFAULT 1, "final_provider" TEXT, "resolved_provider" TEXT, "canonical_slug" TEXT, "original_model_id" TEXT, "affinity_outcome" TEXT, "affinity_pinned_provider" TEXT, "client_session_id" TEXT, "client_session_id_source" TEXT, "fallbacks_json" JSONB, "fallback_count" INTEGER, "model_attempts_json" JSONB, "attempts_truncated" INTEGER NOT NULL DEFAULT 0, "model_attempt_count" INTEGER, "total_provider_attempt_count" INTEGER, "cache_hit_tokens" INTEGER, "cache_miss_tokens" INTEGER, "system_fingerprint" TEXT, "usage_cost" DOUBLE PRECISION, "usage_gateway_cost" DOUBLE PRECISION, "usage_market_cost" DOUBLE PRECISION, "gateway_cost_text" TEXT, "gateway_inference_cost_text" TEXT, "gateway_generation_id" TEXT, "created_at" TEXT NOT NULL DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
CREATE INDEX "upstream_provider_obs_created_idx" ON "upstream_provider_observations" ("created_at");
CREATE INDEX "upstream_provider_obs_model_provider_created_idx" ON "upstream_provider_observations" ("requested_model", "final_provider", "created_at");
CREATE INDEX "upstream_provider_obs_proxy_log_idx" ON "upstream_provider_observations" ("proxy_log_id");
CREATE INDEX "upstream_provider_obs_session_created_idx" ON "upstream_provider_observations" ("client_session_id", "created_at");
CREATE INDEX "upstream_provider_obs_site_provider_created_idx" ON "upstream_provider_observations" ("site_id", "final_provider", "created_at");
